import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function conflict() {
  return Object.assign(new Error('Batch ID already used'), { code: 'ERR_BATCH_CONFLICT' });
}

function corrupt(file) {
  return Object.assign(new Error(`Corrupt ledger file: ${file}`), { code: 'ERR_LEDGER_CORRUPT' });
}

// Returns a normalized copy, or null when the shape is invalid. -0 becomes 0 so the
// in-memory result matches what JSON round-tripping yields.
function normalize(batch) {
  if (!batch || typeof batch !== 'object' || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) return null;
  const entries = [];
  for (let i = 0; i < batch.entries.length; i++) {
    const entry = batch.entries[i];
    if (!entry || typeof entry !== 'object' || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) return null;
    entries.push({ key: entry.key, delta: entry.delta === 0 ? 0 : entry.delta });
  }
  return { id: batch.id, entries };
}

function validate(batch) {
  const normalized = normalize(batch);
  if (!normalized) throw invalid();
  return normalized;
}

function sameEntries(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i].key !== b[i].key || a[i].delta !== b[i].delta) return false;
  }
  return true;
}

function initialState() {
  return { revision: 0, balances: {}, receipts: [] };
}

function checkState(value, file) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw corrupt(file);
  const { revision, balances, receipts } = value;
  if (!Number.isSafeInteger(revision) || revision < 0) throw corrupt(file);
  if (!balances || typeof balances !== 'object' || Array.isArray(balances)) throw corrupt(file);
  for (const key of Object.keys(balances)) {
    if (!KEY.test(key) || !Number.isSafeInteger(balances[key])) throw corrupt(file);
  }
  if (!Array.isArray(receipts) || receipts.length !== revision) throw corrupt(file);
  for (const receipt of receipts) if (!normalize(receipt)) throw corrupt(file);
  return { revision, balances, receipts };
}

function checkPending(value, file) {
  if (!value || typeof value !== 'object' || !Number.isSafeInteger(value.baseRevision) || value.baseRevision < 0) throw corrupt(file);
  const batch = normalize(value.batch);
  if (!batch) throw corrupt(file);
  return { baseRevision: value.baseRevision, batch };
}

async function readJson(io, file) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return undefined; throw error; }
  return JSON.parse(text);
}

// Stage to <name>.tmp, then atomically replace <name>.json. A partial staging write or a
// failed rename leaves the previous <name>.json intact.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (!error || error.code !== 'ENOENT') throw error; }
}

function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) throw invalid();
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

function isPublished(state, pending) {
  if (state.revision !== pending.baseRevision + 1) return false;
  const last = state.receipts[state.receipts.length - 1];
  return last.id === pending.batch.id && sameEntries(last.entries, pending.batch.entries);
}

// Read-only: determines the committed snapshot and what is needed to make it durable.
async function load(io, directory) {
  const ledgerFile = path.join(directory, 'ledger.json');
  const pendingFile = path.join(directory, 'pending.json');
  const raw = await readJson(io, ledgerFile);
  const durable = raw === undefined ? initialState() : checkState(raw, ledgerFile);
  const rawPending = await readJson(io, pendingFile);
  if (rawPending === undefined) return { state: durable, publish: false, cleanup: false };
  const pending = checkPending(rawPending, pendingFile);
  if (isPublished(durable, pending)) return { state: durable, publish: false, cleanup: true };
  if (durable.revision !== pending.baseRevision || durable.receipts.some(r => r.id === pending.batch.id)) throw corrupt(pendingFile);
  let state;
  try { state = apply(durable, pending.batch); }
  catch { throw corrupt(pendingFile); }
  return { state, publish: true, cleanup: true };
}

async function finish(io, directory, { state, publish, cleanup }) {
  if (publish) await save(io, directory, 'ledger', state);
  if (cleanup) await removePending(io, directory);
  return state;
}

export async function recoverLedger(directory, { io = fs } = {}) {
  await io.mkdir(directory, { recursive: true });
  return finish(io, directory, await load(io, directory));
}

export async function commitBatch(directory, batch, { io = fs, checkpoint } = {}) {
  batch = validate(batch);
  const recovery = await load(io, directory);
  const current = recovery.state;
  const existing = current.receipts.find(receipt => receipt.id === batch.id);
  // Fully decide the new batch (conflict/overflow) before touching durable data.
  const next = existing ? null : apply(current, batch);
  await io.mkdir(directory, { recursive: true });
  await finish(io, directory, recovery);
  if (existing) {
    if (!sameEntries(existing.entries, batch.entries)) throw conflict();
    return current;
  }
  await save(io, directory, 'pending', { baseRevision: current.revision, batch });
  if (checkpoint) await checkpoint('prepared');
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
