import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const A = { id: 'a', entries: [{ key: 'cash', delta: 5 }, { key: 'cash', delta: 1 }] };
const B = { id: 'b', entries: [{ key: 'cash', delta: -2 }, { key: 'bank', delta: 4 }] };
const expected = { revision: 2, balances: { cash: 4, bank: 4 }, receipts: [A, B] };

function faulty(failAt, partial) {
  let n = 0;
  const wrap = name => async (...args) => {
    if (n++ === failAt) {
      if (partial && name === 'writeFile') await fs.writeFile(args[0], String(args[1]).slice(0, 7));
      throw Object.assign(new Error(`injected ${name}`), { code: 'EIO' });
    }
    return fs[name](...args);
  };
  return { mkdir: wrap('mkdir'), readFile: wrap('readFile'), writeFile: wrap('writeFile'), rename: wrap('rename'), unlink: wrap('unlink'), get count() { return n; } };
}

let cases = 0;
for (const partial of [false, true]) {
  for (let failAt = 0; failAt < 40; failAt++) {
    for (const mode of ['recover', 'retry']) {
      const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sweep-'));
      await fs.writeFile(path.join(dir, 'unrelated.txt'), 'x');
      await commitBatch(dir, A);
      const io = faulty(failAt, partial);
      let threw = false;
      try { await commitBatch(dir, B, { io }); } catch (e) { threw = true; assert.equal(e.code, 'EIO'); }
      if (!threw && failAt >= io.count) { await fs.rm(dir, { recursive: true }); continue; }
      if (mode === 'recover') {
        const r = await recoverLedger(dir);
        if (r.revision === 2) assert.deepEqual(r, expected);
        else assert.deepEqual(r, { revision: 1, balances: { cash: 6 }, receipts: [A] });
        assert.deepEqual(await recoverLedger(dir), r);
      }
      assert.deepEqual(await commitBatch(dir, B), expected);
      assert.deepEqual(await recoverLedger(dir), expected);
      await fs.access(path.join(dir, 'unrelated.txt'));
      await fs.rm(dir, { recursive: true });
      cases++;
    }
  }
}

for (const phase of ['prepared', 'published', 'complete']) {
  for (const mode of ['recover', 'retry', 'other']) {
    const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sweep-'));
    await commitBatch(dir, A);
    const err = new Error(phase);
    const seen = [];
    await assert.rejects(commitBatch(dir, B, { checkpoint: async p => { seen.push(p); if (p === phase) throw err; } }), e => e === err);
    if (mode === 'recover') assert.deepEqual(await recoverLedger(dir), expected);
